function CatHouseMatchPopupOtherCat:FreshUI(otherCatData, otherCatOwnerInfo, matchType, consumePrice)
    local isShowCat = otherCatData ~= nil
    KTool.SetActive(self.BeforeChoose.gameObject, not isShowCat)
    KTool.SetActive(self.AfterChoose.gameObject, isShowCat)
    if isShowCat then
        self:FreshCatNode(self.CatHouseListBtnNode, otherCatData)
        local isRally = consumePrice ~= nil
        KTool.SetActive(self.TextTitle.gameObject, isRally)
        KTool.SetActive(self.TextPlayerName.gameObject, not isRally)
        self.TextPlayerName.text = isRally and localize("集会猫咪") or otherCatOwnerInfo.name

        KTool.SetActive(self.BtnClose.gameObject, matchType ~= MatchType.FriendMatchComplete)
    end
end

function CatHouseMatchPopupOtherCat:FreshCatNode(node, catData)
    ---@type CatHouseListBtnNode
    local env = CfUtils.GetLuaScr(node, CatHouseListBtnNodeEnvPath)
    if isNull(env) then return end
    env:FreshCommonUI(catData)
end
